    public void add_shader_texture_uniform(Control owner,VBoxContainer parent,Resource property,Variant getValue,Variant setValue,Resource? actor,Resource? fileOwner)
    {
        var noise=noise_object_from_value(owner,Invoke(owner,getValue));string stateId=actor!=null?actor.Get("id").AsString():"FileResource:"+(fileOwner?.ResourcePath??"");string stateKey="ShaderTexture:"+property.Get("id").AsString();var editor=new VBoxContainer();var state=Ui<Resource>(owner,"ui_state");bool expanded=noise!=null&&_state.category_expanded(state,stateId,stateKey);var row=new HBoxContainer();parent.AddChild(row);var expand=Callable.From(()=>{if(noise==null)return false;expanded=!expanded;editor.Visible=expanded;_state.set_category_expanded(state,stateId,stateKey,expanded);return true;});add_file_resource_slot(owner,row,property,getValue,setValue,Variant.From(expand),default);parent.AddChild(editor);editor.Visible=expanded;if(noise==null)return;var definition=_definitions.get_object_definition(Ui<RefCounted>(owner,"registry"),"noise_image");if(definition==null)return;var panel=new PanelContainer();panel.AddThemeStyleboxOverride("panel",resource_box());editor.AddChild(panel);var fields=new VBoxContainer();fields.AddThemeConstantOverride("separation",7);panel.AddChild(fields);add_image_object_preview(owner,noise,fields);string current="";VBoxContainer? group=null;foreach(var value in definition.Get("properties").AsGodotArray()){var propertyItem=value.As<Resource>();string name=propertyItem.Get("options").AsGodotDictionary().GetValueOrDefault("group","Properties").AsString();if(name!=current){current=name;group=stateful_category(owner,current,stateId,fields,stateKey);}if(actor!=null)add_object_value(owner,actor,noise,definition,propertyItem,group??fields);else add_file_object_value(owner,noise,definition,propertyItem,group??fields,fileOwner);}
    }
    private static GodotObject? Clipboard()=>GD.Load<GDScript>("res://scripts/clipboard/super_clipboard_service.gd").Get("instance").AsGodotObject();
    public void file_resource_menu_action(Control owner,int id,Resource property,Variant getValue,Variant setValue)
    {
        void Set(Variant value)=>Invoke(owner,setValue,value);switch(id){case 6:Clipboard()?.Call("quick_save",Invoke(owner,getValue),property.Get("label"));break;case 5:var definition=_definitions.get_object_definition(Ui<RefCounted>(owner,"registry"),"noise_image");if(definition!=null)Set(_data.from_object(_definitions.create_object(definition)));break;case 0:if(is_shader_property(property)){var shader=new Shader{ResourceName="Shader",Code=property.Get("options").AsGodotDictionary().GetValueOrDefault("new_file_template","shader_type spatial;\n").AsString()};Set(shader);open_shader_resource(owner,Invoke(owner,getValue),false,default);}else if(is_mesh_property(property))Set(new BoxMesh{ResourceName="Mesh"});else{using var image=Image.CreateEmpty(1,1,false,Image.Format.Rgba8);image.Fill(Colors.Transparent);var texture=ImageTexture.CreateFromImage(image);texture.ResourceName="Image";Set(texture);}break;case 2:var embedded=file_resource_to_embedded(Invoke(owner,getValue),property);if(embedded!=null){Set(embedded);if(is_shader_property(property))open_shader_resource(owner,Invoke(owner,getValue),false,default);}break;case 4:Set(default);break;}
    }
    public void picked_file_resource(Control owner,Resource property,Variant setValue,string path){if(path==GD.Load<GDScript>("res://scripts/actors/core/actor_project_file_picker.gd").GetScriptConstantMap()["EMPTY_RESOURCE"].AsString()){Invoke(owner,setValue,default(Variant));return;}if(path.Length==0)return;Invoke(owner,setValue,path);if(is_shader_property(property))open_shader_resource(owner,path,false,default);}
    public void assign_file_reference(Control owner,Resource data,Resource property,Resource root,Variant value){set_file_value(owner,data,property,property,root,value);inspect_file_resource(owner,root.ResourcePath);}
    public void load_file_reference(Control owner,Resource data,Resource property,Resource root,string path)
    {
        if(path==GD.Load<GDScript>("res://scripts/actors/core/actor_project_file_picker.gd").GetScriptConstantMap()["EMPTY_RESOURCE"].AsString()){assign_file_reference(owner,data,property,root,default);return;}if(path.Length==0)return;var loaded=path.GetExtension().ToLowerInvariant() is "tres" or "res"?ResourceLoader.Load(path):null;var registry=Ui<RefCounted>(owner,"registry");if(ActorDataOperations.ScriptIs(loaded,"res://scripts/actors/core/actor_object_data.gd")&&_definitions.object_type_matches(registry,loaded!.Get("type_id").AsStringName(),property.Get("object_type").AsStringName()))assign_file_reference(owner,data,property,root,_data.from_asset(path,loaded.Get("type_id").AsStringName()));else if(property.Get("object_type").AsString()=="image"){var imageDefinition=_definitions.get_object_definition(registry,"image");if(imageDefinition==null)return;var image=_definitions.create_object(imageDefinition);image.Get("values").AsGodotDictionary()[new StringName("source")]=path;assign_file_reference(owner,data,property,root,_data.from_object(image));}
    }
    public void add_file_object_reference(Control owner,Resource data,Resource property,VBoxContainer parent,Resource root)
    {
        add_label(parent,property.Get("label").AsString());var value=_data.object_get_value(data,property.Get("id").AsStringName(),default);var reference=value.VariantType==Variant.Type.Object?value.AsGodotObject() as Resource:null;var resolved=reference!=null?owner.Call("_resolve_object",reference).As<Resource>():null;var row=new HBoxContainer();parent.AddChild(row);var slot=new ActorResourceSlot();slot.Text=resolved!=null?"▸  "+resolved.Get("type_id").AsString().Capitalize():"<empty>";slot.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;slot.ClipText=true;slot.ToggleMode=true;row.AddChild(slot);var menu=new MenuButton{Text="⋯"};row.AddChild(menu);var registry=Ui<RefCounted>(owner,"registry");var definitions=_definitions.object_definitions_for(registry,property.Get("object_type").AsStringName());for(int i=0;i<definitions.Count;i++)menu.GetPopup().AddItem("New "+definitions[i].As<Resource>().Get("display_name").AsString(),100+i);foreach(var entry in new[]{(1,"Load from project…"),(2,"Load from Super Clipboard…"),(3,"Make Unique"),(4,"Copy to Super Clipboard"),(5,"Clear")})menu.GetPopup().AddItem(entry.Item2,entry.Item1);owner.Call("_configure_object_slot",slot,property);slot.Connect("file_dropped",Callable.From<string>(path=>load_file_reference(owner,data,property,root,path)));menu.GetPopup().IdPressed+=id=>{if(id>=100&&id-100<definitions.Count)assign_file_reference(owner,data,property,root,_data.from_object(_definitions.create_object(definitions[(int)id-100].As<Resource>())));else if(id is 1 or 2)owner.Call("_pick_file_reference",data,property,root,id==2);else if(id==3&&resolved!=null)assign_file_reference(owner,data,property,root,_data.from_object(_data.copy_object(resolved)));else if(id==4&&resolved!=null)Clipboard()?.Call("quick_save",resolved,property.Get("label"));else if(id==5)assign_file_reference(owner,data,property,root,default);};if(resolved==null)return;var children=new VBoxContainer{Visible=false};parent.AddChild(children);slot.Toggled+=children.SetVisible;if(_definitions.object_type_matches(registry,resolved.Get("type_id").AsStringName(),"image"))add_image_object_preview(owner,resolved,children);var definition=_definitions.get_object_definition(registry,resolved.Get("type_id").AsStringName());if(definition==null)return;foreach(var item in definition.Get("properties").AsGodotArray()){var child=item.As<Resource>();if(property_is_visible(owner,child,resolved))add_file_object_value(owner,resolved,definition,child,children,root);}
    }
